export const MEDS = [ {e:'💊',n:'Acetaminofén',cat:'Analgésico',catCls:'cat-analg',dose:'500 mg',uso:'Alivia el dolor leve a moderado y reduce la fiebre. Es uno de los analgésicos más seguros y usados a nivel mundial.',dosis:'500–1000 mg cada 6–8 horas. Máximo 4 g/día en adultos.',cuando:'Dolor de cabeza, fiebre, dolor muscular, molestias generales.',prec:['No superar 4 gramos al día','Evitar con alcohol','Precaución en enfermedades hepáticas','No combinar con otros productos que contengan paracetamol'],dico:'Es mi primer consejo cuando hay fiebre o dolor leve. Muy seguro si se toma bien. ¡Ojo con la dosis!'},
  {e:'💊',n:'Ibuprofeno',cat:'Analgésico',catCls:'cat-analg',dose:'400 mg',uso:'Antiinflamatorio no esteroideo (AINE). Alivia el dolor, reduce la inflamación y baja la fiebre.',dosis:'400–600 mg cada 6–8 horas. Tomar con alimentos.',cuando:'Dolor muscular, articular, menstrual, dolor de cabeza, fiebre, golpes.',prec:['Tomar siempre con comida para proteger el estómago','No usar con úlcera gástrica activa','Evitar en el tercer trimestre del embarazo','No combinar con aspirina sin indicación médica'],dico:'Ideal para golpes e inflamación. Siempre acompáñalo con una comida, así no irrita el estómago.'},
  {e:'💊',n:'Aspirina',cat:'Analgésico',catCls:'cat-analg',dose:'500 mg',uso:'Analgésico, antipirético y antiagregante plaquetario.',dosis:'500 mg cada 8 horas para dolor.',cuando:'Dolor, fiebre, prevención cardiovascular (solo con prescripción).',prec:['No dar a niños menores de 12 años','Tomar con alimentos','Evitar si hay problemas de coagulación'],dico:'La aspirina es antigua pero efectiva. En niños: nunca. Para el corazón: solo con tu médico.'},
  {e:'🔵',n:'Loratadina',cat:'Antihistamínico',catCls:'cat-antih',dose:'10 mg',uso:'Antihistamínico de segunda generación. Alivia síntomas de alergias sin causar mucho sueño.',dosis:'10 mg una vez al día.',cuando:'Rinitis alérgica, urticaria, alergia al polvo o pólenes, picaduras.',prec:['Puede causar algo de somnolencia','Evitar conducir si hay somnolencia','Precaución en insuficiencia hepática'],dico:'Mi favorita para las alergias. No da tanto sueño y funciona todo el día con una sola dosis.'},
  {e:'🔵',n:'Cetirizina',cat:'Antihistamínico',catCls:'cat-antih',dose:'10 mg',uso:'Antihistamínico que alivia síntomas de alergia estacional y urticaria crónica.',dosis:'10 mg una vez al día, preferiblemente en la noche.',cuando:'Alergias, urticaria, eccema alérgico, ojos llorosos por alergia.',prec:['Puede causar somnolencia: preferir de noche','No combinar con alcohol','Precaución al manejar maquinaria'],dico:'Si tienes alergia y además te cuesta dormir, la cetirizina tomada de noche te ayuda con ambos.'},
  {e:'🟣',n:'Amoxicilina',cat:'Antibiótico',catCls:'cat-antib',dose:'500 mg',uso:'Antibiótico de amplio espectro. Trata infecciones bacterianas como amigdalitis, otitis, bronquitis.',dosis:'500 mg cada 8 horas por 7–10 días.',cuando:'Solo con indicación médica. Infecciones confirmadas por bacteria.',prec:['Completar SIEMPRE el tratamiento','No tomar sin prescripción médica','Puede causar diarrea o molestia estomacal'],dico:'Los antibióticos son serios. Solo úsame si el médico lo indica. ¡Y completa el tratamiento!'},
  {e:'🟣',n:'Azitromicina',cat:'Antibiótico',catCls:'cat-antib',dose:'500 mg',uso:'Antibiótico macrólido. Trata infecciones respiratorias y de piel.',dosis:'500 mg una vez al día por 3–5 días.',cuando:'Solo con prescripción. Neumonía leve, sinusitis, infecciones de piel.',prec:['Uso exclusivamente con prescripción médica','Puede alterar el ritmo cardíaco en dosis altas','Completar el tratamiento'],dico:'Azitromicina se toma pocos días pero actúa varios días más en el cuerpo. No la uses sin tu médico.'},
  {e:'🟢',n:'Omeprazol',cat:'Gastroprotector',catCls:'cat-gast',dose:'20 mg',uso:'Reduce la producción de ácido en el estómago. Trata gastritis, úlcera y reflujo.',dosis:'20 mg una vez al día, en ayunas, 30 minutos antes del desayuno.',cuando:'Acidez, gastritis, reflujo, úlcera.',prec:['Tomar en ayunas para mayor eficacia','No romper ni masticar la cápsula','Consultar médico si síntomas persisten más de 2 semanas'],dico:'Cuando el estómago arde, omeprazol al rescate. Mejor tomarlo antes del desayuno.'},
  {e:'🟢',n:'Ranitidina',cat:'Gastroprotector',catCls:'cat-gast',dose:'150 mg',uso:'Reduce la producción de ácido gástrico. Trata úlceras, reflujo y gastritis.',dosis:'150 mg dos veces al día.',cuando:'Acidez puntual, gastritis, reflujo leve.',prec:['Evitar en problemas renales sin ajuste','Puede interactuar con otros medicamentos'],dico:'La ranitidina es una buena opción para la acidez rápida. Si el problema es frecuente, visita al médico.'},
  {e:'💛',n:'Vitamina C',cat:'Vitamina',catCls:'cat-vita',dose:'500 mg',uso:'Antioxidante esencial. Refuerza el sistema inmune y mejora la absorción de hierro.',dosis:'500–1000 mg al día.',cuando:'Prevención de resfriados, refuerzo inmune, suplemento diario.',prec:['Dosis muy altas pueden causar diarrea','Los cítricos son la fuente natural más recomendada'],dico:'¡La vitamina C es mi aliada! Especialmente en temporada de gripes.'},
  {e:'💛',n:'Vitamina D3',cat:'Vitamina',catCls:'cat-vita',dose:'1000 UI',uso:'Esencial para absorción de calcio, salud ósea y función inmunológica.',dosis:'1000–2000 UI al día con una comida con grasas.',cuando:'Suplemento diario, especialmente con poca exposición solar.',prec:['No exceder 4000 UI/día sin indicación médica','Tomar con comidas con grasa'],dico:'El sol es la mejor fuente de vitamina D, pero si no te da mucho el sol, un suplemento ayuda.'},
  {e:'🩺',n:'Metformina',cat:'Antidiabético',catCls:'cat-card',dose:'500 mg',uso:'Medicamento de primera línea para diabetes tipo 2.',dosis:'500–1000 mg con las comidas.',cuando:'Únicamente bajo prescripción médica para diabetes tipo 2.',prec:['USO EXCLUSIVO CON PRESCRIPCIÓN MÉDICA','Tomar siempre con comida','No usar con función renal deteriorada'],dico:'La metformina es un medicamento serio para la diabetes. Solo con receta médica y seguimiento regular.'},
  {e:'❤️',n:'Enalapril',cat:'Cardiovascular',catCls:'cat-card',dose:'10 mg',uso:'Trata la hipertensión arterial y la insuficiencia cardíaca.',dosis:'5–20 mg una vez al día.',cuando:'Solo bajo prescripción médica para hipertensión.',prec:['USO EXCLUSIVO CON PRESCRIPCIÓN MÉDICA','No suspender bruscamente','Puede causar tos seca'],dico:'La presión alta es silenciosa pero peligrosa. Si te lo recetaron, tómalo todos los días.'},
  {e:'🫁',n:'Salbutamol',cat:'Respiratorio',catCls:'cat-resp',dose:'100 mcg',uso:'Broncodilatador de acción rápida. Alivia el broncoespasmo en asma.',dosis:'1–2 inhalaciones cuando sea necesario.',cuando:'Crisis asmática, dificultad respiratoria.',prec:['No usar sin prescripción','Uso frecuente indica asma mal controlada','Siempre cargar el inhalador de rescate'],dico:'Si tienes asma, el salbutamol es tu salvavidas en una crisis. ¡Siempre tenlo a mano!'},
  {e:'🫁',n:'Ambroxol',cat:'Respiratorio',catCls:'cat-resp',dose:'30 mg',uso:'Mucolítico. Adelgaza el moco y facilita su expulsión.',dosis:'30 mg tres veces al día con abundante agua.',cuando:'Bronquitis, tos con flema, catarro.',prec:['Beber mucha agua para potenciar el efecto','No combinar con antitusivos','No usar en tos seca'],dico:'Cuando hay mucho moco y la tos no cede, el ambroxol ayuda a expulsarlo. ¡Agua, agua y más agua!'},
  {e:'🌿',n:'Diclofenaco',cat:'Analgésico',catCls:'cat-analg',dose:'50 mg',uso:'Antiinflamatorio potente. Trata dolor agudo con componente inflamatorio.',dosis:'50 mg dos o tres veces al día con alimentos.',cuando:'Dolor articular, lumbalgia, golpes con inflamación.',prec:['Siempre con alimentos — irrita el estómago','No usar con úlcera activa','No combinar con otros AINEs'],dico:'Diclofenaco es poderoso para la inflamación. Siempre con comida y no más tiempo del necesario.'},
  {e:'💊',n:'Tramadol',cat:'Analgésico',catCls:'cat-analg',dose:'50 mg',uso:'Analgésico opioide para dolor moderado a intenso.',dosis:'50–100 mg cada 4–6 horas. Solo bajo prescripción.',cuando:'SOLO CON PRESCRIPCIÓN MÉDICA.',prec:['REQUIERE RECETA MÉDICA','Puede causar dependencia','No conducir ni usar maquinaria'],dico:'El tramadol es para dolores fuertes y solo con receta. Nunca te automediques con este.'},
  {e:'🟡',n:'Metoclopramida',cat:'Gastroprotector',catCls:'cat-gast',dose:'10 mg',uso:'Antiemético. Alivia las náuseas y vómitos.',dosis:'10 mg tres veces al día, 30 minutos antes de las comidas.',cuando:'Náuseas, vómitos, sensación de llenura.',prec:['No usar más de 5 días sin indicación','Puede causar somnolencia','Evitar con Parkinson'],dico:'Cuando el estómago no quiere cooperar y hay náuseas, la metoclopramida ayuda a calmarlo.'},
  {e:'🔴',n:'Hidrocortisona crema',cat:'Dermatológico',catCls:'cat-derm',dose:'1%',uso:'Corticoide tópico. Reduce inflamación y picor en condiciones alérgicas de piel.',dosis:'Aplicar capa fina en zona afectada 1–3 veces al día.',cuando:'Eccema leve, dermatitis, picazón por alergia.',prec:['No aplicar en cara sin indicación','No usar más de 7 días sin consultar','Evitar en zonas infectadas'],dico:'Para el picor y la irritación de piel, la hidrocortisona crema funciona bien. Poquito y pocos días.'},
  {e:'🔴',n:'Clotrimazol crema',cat:'Dermatológico',catCls:'cat-derm',dose:'1%',uso:'Antifúngico tópico. Trata infecciones por hongos.',dosis:'Aplicar capa fina 2–3 veces al día por 2–4 semanas.',cuando:'Hongos en piel, pie de atleta, candidiasis.',prec:['Completar el tratamiento','Mantener la zona limpia y seca','Consultar si no mejora en 2 semanas'],dico:'Los hongos en la piel se tratan. La clave es completar el tratamiento y mantener la zona seca.'},
  {e:'🫧',n:'Solución salina',cat:'Respiratorio',catCls:'cat-resp',dose:'0.9%',uso:'Higiene nasal. Limpia y humedece las mucosas nasales.',dosis:'2–3 gotas en cada fosa nasal, 3–4 veces al día.',cuando:'Congestión nasal, catarro, rinitis.',prec:['Completamente segura para todas las edades','Usar solución estéril o de farmacia'],dico:'La solución salina es de mis mejores amigas. Sin efectos secundarios, segura para todos. ¡Siempre tenla!'},
  {e:'💧',n:'Suero oral (SRO)',cat:'Gastroprotector',catCls:'cat-gast',dose:'Sachet',uso:'Sales de rehidratación oral. Repone líquidos y electrolitos perdidos.',dosis:'Disolver un sobre en 1 litro de agua. Beber a sorbos frecuentes.',cuando:'Diarrea, vómitos, deshidratación.',prec:['No sustituir comidas','Si vómitos severos persisten ir al médico','Preparar fresco y consumir en 24 horas'],dico:'Cuando hay diarrea o vómito, lo primero es no deshidratarse. El suero oral es simple y muy efectivo.'},
  {e:'💊',n:'Loperamida',cat:'Gastroprotector',catCls:'cat-gast',dose:'2 mg',uso:'Antidiarreico. Reduce la frecuencia de deposiciones en diarrea aguda.',dosis:'2 mg tras cada deposición blanda. Máximo 8 mg/día.',cuando:'Diarrea aguda no infecciosa.',prec:['NO usar si hay fiebre alta o sangre','No usar en niños menores de 2 años','Combinar con suero oral'],dico:'La loperamida detiene la diarrea rápido. Si hay fiebre o sangre, eso necesita médico.'},
  {e:'🌿',n:'Melatonina',cat:'Vitamina',catCls:'cat-vita',dose:'3 mg',uso:'Regula el ciclo de sueño. Ayuda a conciliar el sueño.',dosis:'0.5–3 mg, 30 minutos antes de dormir.',cuando:'Insomnio leve, jet lag, desfase del ciclo de sueño.',prec:['No sustituye tratamiento de insomnio crónico','Puede causar somnolencia matutina','Evitar conducir después de tomarla'],dico:'Si tienes dificultad para dormir, la melatonina puede ayudar a resetear tu reloj interno.'},
  {e:'💊',n:'Losartán',cat:'Cardiovascular',catCls:'cat-card',dose:'50 mg',uso:'Trata la hipertensión arterial.',dosis:'25–100 mg una vez al día.',cuando:'Solo bajo prescripción médica.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','No suspender sin consultar','Evitar en embarazo'],dico:'El losartán mantiene la presión bajo control. La hipertensión no duele pero daña silenciosamente.'},
  {e:'🩹',n:'Clorfeniramina',cat:'Antihistamínico',catCls:'cat-antih',dose:'4 mg',uso:'Antihistamínico de primera generación. Alivia síntomas de alergia y resfriado.',dosis:'4 mg cada 4–6 horas.',cuando:'Rinitis alérgica, urticaria, picazón.',prec:['Causa somnolencia — no conducir','No combinar con alcohol','Puede causar boca seca'],dico:'La clorfeniramina funciona muy bien para la alergia, pero da bastante sueño. Perfecta para tomar de noche.'},
  {e:'🌡️',n:'Naproxeno',cat:'Analgésico',catCls:'cat-analg',dose:'550 mg',uso:'Antiinflamatorio de larga duración.',dosis:'250–550 mg dos veces al día con comida.',cuando:'Dolor menstrual, artritis, dolor muscular.',prec:['Siempre con alimentos','No combinar con otros AINEs','Uso prolongado requiere supervisión'],dico:'El naproxeno dura más que el ibuprofeno. Genial para el dolor menstrual, pero siempre con comida.'},
  {e:'💊',n:'Pantoprazol',cat:'Gastroprotector',catCls:'cat-gast',dose:'40 mg',uso:'Inhibidor de la bomba de protones. Trata reflujo severo y úlceras.',dosis:'40 mg una vez al día en ayunas.',cuando:'Reflujo severo, úlcera péptica.',prec:['Tomar en ayunas estrictos','Uso prolongado puede reducir absorción de magnesio'],dico:'El pantoprazol es más potente para el reflujo severo. Si el omeprazol no alcanzó, este puede ser la respuesta.'},
  {e:'🩺',n:'Atorvastatina',cat:'Cardiovascular',catCls:'cat-card',dose:'20 mg',uso:'Reduce colesterol LDL y triglicéridos. Previene eventos cardiovasculares.',dosis:'10–80 mg una vez al día, en la noche.',cuando:'Solo bajo prescripción para hipercolesterolemia.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Tomar de noche','Puede causar dolores musculares'],dico:'El colesterol alto no se siente pero obstruye las arterias. La atorvastatina trabaja mejor mientras duermes.'},
  {e:'🌿',n:'Zinc',cat:'Vitamina',catCls:'cat-vita',dose:'20 mg',uso:'Mineral esencial para el sistema inmune y cicatrización.',dosis:'20–50 mg al día con alimentos.',cuando:'Suplemento inmune, durante resfriados.',prec:['No exceder 40 mg/día sin indicación','Tomar con comida para evitar náuseas'],dico:'El zinc ayuda al sistema inmune y acelera la recuperación del resfriado. Un gran aliado en temporadas de gripe.'},

  // === ANALGÉSICOS ===
  {e:'💊',n:'Ketorolaco',cat:'Analgésico',catCls:'cat-analg',dose:'10 mg',uso:'Antiinflamatorio no esteroideo de potencia alta. Para dolor agudo e intenso.',dosis:'10 mg cada 4–6 horas. Máximo 5 días de uso.',cuando:'Dolor postoperatorio, cólico renal, dolor dental intenso.',prec:['Uso máximo 5 días','Siempre con alimentos','No usar en úlcera ni insuficiencia renal','No combinar con otros AINEs'],dico:'El ketorolaco es uno de los AINEs más potentes. Eficaz para dolores fuertes, pero solo por pocos días.'},
  {e:'🌿',n:'Cafeína + Acetaminofén',cat:'Analgésico',catCls:'cat-analg',dose:'65/500 mg',uso:'Combinación que potencia el efecto analgésico. Usada para cefalea y migraña.',dosis:'1 tableta cada 6 horas según necesidad.',cuando:'Dolor de cabeza, migraña leve, cefalea tensional.',prec:['No exceder 4 dosis al día','Evitar en taquicardia o ansiedad','No combinar con otros que contengan paracetamol'],dico:'La cafeína potencia el acetaminofén y lo hace más efectivo para el dolor de cabeza. ¡Pero cuidado si eres sensible al café!'},
  {e:'💊',n:'Meloxicam',cat:'Analgésico',catCls:'cat-analg',dose:'15 mg',uso:'AINE selectivo con menor irritación gástrica. Para dolor inflamatorio crónico.',dosis:'7.5–15 mg una vez al día con comida.',cuando:'Artritis, artrosis, dolor articular crónico.',prec:['Tomar con alimentos','No usar con úlcera activa','Requiere control médico para uso prolongado'],dico:'El meloxicam es más amigable con el estómago que otros AINEs. Buena opción para dolores articulares crónicos.'},
  {e:'🌿',n:'Metamizol',cat:'Analgésico',catCls:'cat-analg',dose:'500 mg',uso:'Analgésico y antipirético potente. Eficaz para dolores cólicos y fiebre alta.',dosis:'500–1000 mg cada 6–8 horas.',cuando:'Cólicos, fiebre alta resistente, dolor visceral.',prec:['Puede causar hipotensión en inyección rápida','Raramente causa agranulocitosis','No automedicar en embarazo'],dico:'El metamizol va muy bien para los cólicos. Actúa rápido y baja la fiebre con eficacia.'},

  // === ANTIBIÓTICOS ===
  {e:'🟣',n:'Ciprofloxacino',cat:'Antibiótico',catCls:'cat-antib',dose:'500 mg',uso:'Antibiótico fluoroquinolona. Amplio espectro para infecciones urinarias y gastrointestinales.',dosis:'500 mg cada 12 horas por 7–10 días.',cuando:'Solo con prescripción. Infecciones urinarias, gastrointestinales.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Tomar con abundante agua','Evitar con antiácidos','Puede dañar tendones en adultos mayores'],dico:'El ciprofloxacino es muy efectivo para infecciones urinarias, pero es un antibiótico serio. Solo con receta.'},
  {e:'🟣',n:'Metronidazol',cat:'Antibiótico',catCls:'cat-antib',dose:'500 mg',uso:'Antibiótico y antiparasitario. Trata infecciones por anaerobios y parásitos.',dosis:'500 mg cada 8 horas por 7 días.',cuando:'Solo con prescripción. Amebiasis, giardiasis, vaginosis bacteriana.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','No tomar con alcohol — reacción grave','Puede causar náuseas y sabor metálico'],dico:'El metronidazol es el campeón contra ciertos parásitos. Recuerda: ni una gota de alcohol mientras lo tomes.'},
  {e:'🟣',n:'Claritromicina',cat:'Antibiótico',catCls:'cat-antib',dose:'500 mg',uso:'Antibiótico macrólido. Trata infecciones respiratorias y Helicobacter pylori.',dosis:'250–500 mg cada 12 horas por 7–14 días.',cuando:'Solo con prescripción. Neumonía, sinusitis, H. pylori.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Puede causar alteraciones del gusto','Varias interacciones con otros medicamentos'],dico:'La claritromicina es aliada contra la bacteria del estómago y las infecciones respiratorias. Solo con indicación médica.'},
  {e:'🟣',n:'Trimetoprim/Sulfametoxazol',cat:'Antibiótico',catCls:'cat-antib',dose:'800/160 mg',uso:'Antibiótico combinado para infecciones urinarias y respiratorias.',dosis:'800/160 mg cada 12 horas por 7–14 días.',cuando:'Solo con prescripción. ITU, bronquitis bacteriana.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Beber mucha agua','Puede causar fotosensibilidad','No usar en embarazo avanzado'],dico:'Una combinación clásica para las infecciones de orina. Hidratación abundante para proteger los riñones.'},
  {e:'🟣',n:'Doxiciclina',cat:'Antibiótico',catCls:'cat-antib',dose:'100 mg',uso:'Antibiótico tetraciclina. Trata infecciones respiratorias, de piel y enfermedades de transmisión vectorial.',dosis:'100 mg cada 12 horas por 7–14 días.',cuando:'Solo con prescripción. Neumonía atípica, acné, dengue.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','No tomar con leche ni antiácidos','Evitar exposición al sol','No usar en menores de 8 años ni embarazadas'],dico:'La doxiciclina cubre muchas infecciones. Si la tomas, protégete del sol porque puede irritar la piel.'},
  {e:'🟣',n:'Amoxicilina/Clavulanato',cat:'Antibiótico',catCls:'cat-antib',dose:'875/125 mg',uso:'Antibiótico de amplio espectro resistente a betalactamasas.',dosis:'875/125 mg cada 12 horas con alimentos.',cuando:'Solo con prescripción. Sinusitis, otitis, infecciones de piel.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Siempre con alimentos','Puede causar diarrea','Completar el tratamiento'],dico:'El augmentín es más potente que la amoxicilina sola. Muy usado cuando hay resistencia bacteriana.'},

  // === ANTIHISTAMÍNICOS ===
  {e:'🔵',n:'Desloratadina',cat:'Antihistamínico',catCls:'cat-antih',dose:'5 mg',uso:'Antihistamínico de tercera generación. Sin somnolencia. Dura 24 horas.',dosis:'5 mg una vez al día.',cuando:'Rinitis alérgica, urticaria crónica, alergias.',prec:['Uno de los que menos sueño da','Precaución en insuficiencia renal'],dico:'La desloratadina es la más moderna de las antihistaminas. Sin sueño, sin molestias, y solo una al día.'},
  {e:'🔵',n:'Fexofenadina',cat:'Antihistamínico',catCls:'cat-antih',dose:'120 mg',uso:'Antihistamínico sin sedación. Muy bien tolerado.',dosis:'120 mg una vez al día o 60 mg dos veces al día.',cuando:'Rinitis alérgica, urticaria, alergia estacional.',prec:['No tomar con jugo de naranja o manzana','Pocos efectos secundarios'],dico:'La fexofenadina es muy segura y no da sueño. Ideal para quienes manejan o trabajan con maquinaria.'},
  {e:'🔵',n:'Difenhidramina',cat:'Antihistamínico',catCls:'cat-antih',dose:'25 mg',uso:'Antihistamínico de primera generación. También usado como inductor del sueño.',dosis:'25–50 mg al momento de acostarse para el sueño.',cuando:'Alergia, insomnio ocasional, mareo por viaje.',prec:['Causa mucho sueño — no conducir','No tomar con alcohol','No usar en personas mayores de forma crónica'],dico:'La difenhidramina da bastante sueño, lo cual a veces es justo lo que se necesita. ¡Pero solo ocasionalmente!'},

  // === GASTROPROTECTORES ===
  {e:'🟢',n:'Esomeprazol',cat:'Gastroprotector',catCls:'cat-gast',dose:'40 mg',uso:'Inhibidor de bomba de protones de nueva generación. Potente control del ácido.',dosis:'40 mg una vez al día en ayunas.',cuando:'Reflujo gastroesofágico, úlcera, gastritis erosiva.',prec:['Tomar en ayunas','No masticar la cápsula','Uso prolongado puede afectar absorción de magnesio y B12'],dico:'El esomeprazol es uno de los más efectivos para el reflujo severo. Tomaolo 30 min antes del desayuno.'},
  {e:'🟢',n:'Sucralfato',cat:'Gastroprotector',catCls:'cat-gast',dose:'1 g',uso:'Protector de la mucosa gástrica. Crea una barrera sobre la úlcera.',dosis:'1 g cuatro veces al día, en ayunas y al acostarse.',cuando:'Úlcera péptica, gastritis, protección gástrica.',prec:['Tomar en ayunas y separado de otros medicamentos','No tomar con antiácidos simultáneamente'],dico:'El sucralfato actúa como un parche sobre la úlcera. Tómalo bien separado de otras pastillas.'},
  {e:'🟢',n:'Domperidona',cat:'Gastroprotector',catCls:'cat-gast',dose:'10 mg',uso:'Procinético. Acelera el vaciamiento gástrico y reduce náuseas.',dosis:'10 mg tres veces al día, 15 minutos antes de las comidas.',cuando:'Náuseas, distensión, digestión lenta, reflujo.',prec:['No usar en problemas cardíacos sin consultar','Uso máximo recomendado de 4 semanas','Puede interactuar con otros medicamentos'],dico:'La domperidona ayuda al estómago a funcionar más rápido. Excelente cuando la comida parece que no pasa.'},
  {e:'🟡',n:'Bicarbonato de sodio',cat:'Gastroprotector',catCls:'cat-gast',dose:'Polvo',uso:'Antiácido de acción rápida. Neutraliza el ácido del estómago temporalmente.',dosis:'Media cucharadita en un vaso de agua fría.',cuando:'Acidez puntual, ardor de estómago.',prec:['Solo para uso ocasional — no crónico','No usar con dieta restringida en sodio','Puede interferir con otros medicamentos'],dico:'El bicarbonato es el remedio más casero para la acidez. Funciona rápido, pero no es para todos los días.'},
  {e:'🟡',n:'Dimeticona',cat:'Gastroprotector',catCls:'cat-gast',dose:'80 mg',uso:'Antiflatulentor. Elimina el gas acumulado en el tracto digestivo.',dosis:'80 mg tres veces al día después de las comidas.',cuando:'Gases, distensión abdominal, meteorismo.',prec:['Muy bien tolerada','No tiene interacciones significativas'],dico:'Cuando el gas no da tregua, la dimeticona al rescate. Segura y sin efectos secundarios importantes.'},

  // === CARDIOVASCULAR ===
  {e:'❤️',n:'Amlodipino',cat:'Cardiovascular',catCls:'cat-card',dose:'5 mg',uso:'Bloqueador de canales de calcio. Trata la hipertensión y angina de pecho.',dosis:'5–10 mg una vez al día.',cuando:'Solo bajo prescripción para hipertensión y angina.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','No suspender bruscamente','Puede causar edema en los tobillos'],dico:'El amlodipino relaja los vasos sanguíneos y baja la presión. Es de los más usados para la hipertensión.'},
  {e:'❤️',n:'Furosemida',cat:'Cardiovascular',catCls:'cat-card',dose:'40 mg',uso:'Diurético de asa. Elimina el exceso de líquido en insuficiencia cardíaca e hipertensión.',dosis:'20–80 mg al día en la mañana.',cuando:'Solo con prescripción médica. Edema, insuficiencia cardíaca.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Tomar en la mañana para no interrumpir el sueño','Vigilar niveles de potasio','Puede causar hipotensión'],dico:'La furosemida hace que el cuerpo elimine líquidos. Siempre por la mañana para que no interrumpa el sueño.'},
  {e:'❤️',n:'Espironolactona',cat:'Cardiovascular',catCls:'cat-card',dose:'25 mg',uso:'Diurético ahorrador de potasio. Útil en insuficiencia cardíaca e hipertensión.',dosis:'25–100 mg al día.',cuando:'Solo con prescripción. Insuficiencia cardíaca, hipertensión, edema.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Puede elevar el potasio — vigilar con dieta','No usar en insuficiencia renal grave'],dico:'La espironolactona es un diurético que no baja el potasio. Se usa mucho en enfermedades del corazón.'},
  {e:'❤️',n:'Metoprolol',cat:'Cardiovascular',catCls:'cat-card',dose:'50 mg',uso:'Betabloqueador. Controla la frecuencia cardíaca y trata hipertensión y angina.',dosis:'50–100 mg dos veces al día.',cuando:'Solo con prescripción. Hipertensión, arritmias, angina.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','No suspender abruptamente','Puede causar bradicardia y frialdad en manos'],dico:'El metoprolol enlentece y regula el corazón. Nunca lo pares de golpe — siempre consulta a tu médico.'},
  {e:'🩺',n:'Glibenclamida',cat:'Antidiabético',catCls:'cat-card',dose:'5 mg',uso:'Sulfonilurea. Estimula la producción de insulina en diabetes tipo 2.',dosis:'2.5–15 mg al día con el desayuno.',cuando:'Solo con prescripción para diabetes tipo 2.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Puede causar hipoglucemia','Tomar con alimentos','No usar en insuficiencia renal grave'],dico:'La glibenclamida estimula al páncreas a producir más insulina. Siempre con comida para evitar bajones de azúcar.'},
  {e:'🩺',n:'Insulina NPH',cat:'Antidiabético',catCls:'cat-card',dose:'100 UI/ml',uso:'Insulina de acción intermedia para control de glucemia en diabetes.',dosis:'Según indicación médica estricta — variable.',cuando:'Únicamente bajo prescripción y supervisión médica.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Requiere control glucémico regular','Vigilar signos de hipoglucemia','Conservar en refrigeración'],dico:'La insulina es esencial para muchos diabéticos. Su dosis es muy personal y debe ser manejada con tu médico.'},

  // === RESPIRATORIO ===
  {e:'🫁',n:'Budesonida inhalada',cat:'Respiratorio',catCls:'cat-resp',dose:'200 mcg',uso:'Corticoide inhalado. Controla la inflamación crónica en asma y EPOC.',dosis:'200–400 mcg dos veces al día (mantenimiento).',cuando:'Asma crónica, EPOC — bajo prescripción médica.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Enjuagar la boca después de inhalar','No reemplaza el salbutamol en crisis aguda'],dico:'La budesonida es para el control diario del asma, no para la crisis. ¡Y siempre enjuaga la boca después!'},
  {e:'🫁',n:'Montelukast',cat:'Respiratorio',catCls:'cat-resp',dose:'10 mg',uso:'Antagonista de leucotrienos. Previene síntomas de asma y rinitis alérgica.',dosis:'10 mg una vez al día en la noche.',cuando:'Solo con prescripción. Asma leve-moderada, rinitis alérgica.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Tomar en la noche','Puede causar cambios de ánimo en algunos pacientes'],dico:'El montelukast ayuda a prevenir las crisis de asma. Se toma de noche y actúa durante el día siguiente.'},
  {e:'🫁',n:'Dextrometorfano',cat:'Respiratorio',catCls:'cat-resp',dose:'15 mg',uso:'Antitusivo. Suprime la tos seca e irritativa.',dosis:'15–30 mg cada 4–6 horas según necesidad.',cuando:'Tos seca, tos irritativa, tos nocturna.',prec:['No usar en tos productiva (con flema)','No combinar con ambroxol','Evitar conducir en altas dosis','No usar en menores de 4 años sin indicación'],dico:'Dextrometorfano frena la tos seca. Pero si hay flema, necesitas un mucolítico — no este.'},
  {e:'🫁',n:'Bromuro de ipratropio',cat:'Respiratorio',catCls:'cat-resp',dose:'20 mcg',uso:'Broncodilatador anticolinérgico. Trata broncoespasmo en EPOC y asma.',dosis:'2 inhalaciones 3–4 veces al día.',cuando:'Solo con prescripción. EPOC, bronquitis crónica, asma.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Puede causar sequedad bucal','Enjuagar boca después de inhalar'],dico:'El ipratropio abre los bronquios de una forma diferente al salbutamol. Muy útil en EPOC.'},
  {e:'🫁',n:'Prednisona',cat:'Respiratorio',catCls:'cat-resp',dose:'20 mg',uso:'Corticoide oral sistémico. Reduce la inflamación en crisis asmáticas y alergias graves.',dosis:'20–60 mg al día según indicación médica, con alimentos.',cuando:'Solo con prescripción. Crisis asmática, alergias graves, inflamación.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','No suspender bruscamente','Puede elevar glucosa y presión','Tomar en la mañana con alimentos'],dico:'La prednisona es potente antiinflamatoria. Muy eficaz pero debe usarse el tiempo justo y suspenderse gradualmente.'},

  // === VITAMINAS Y SUPLEMENTOS ===
  {e:'💛',n:'Complejo B',cat:'Vitamina',catCls:'cat-vita',dose:'Comprimido',uso:'Suplemento de vitaminas del grupo B. Apoya el sistema nervioso y la energía celular.',dosis:'1 comprimido al día con el desayuno.',cuando:'Fatiga, suplemento en embarazo, deficiencias nutricionales.',prec:['Puede colorear la orina de amarillo — es normal','Exceso de B6 puede causar neuropatía'],dico:'El complejo B es el suplemento de la energía. Si te sientes fatigado sin causa clara, puede ayudarte.'},
  {e:'💛',n:'Ácido fólico',cat:'Vitamina',catCls:'cat-vita',dose:'400 mcg',uso:'Vitamina B9. Esencial en el embarazo para prevenir defectos del tubo neural.',dosis:'400–800 mcg al día.',cuando:'Embarazo o planeación del mismo, anemia megaloblástica.',prec:['Fundamental en las primeras semanas de embarazo','Dosis altas requieren supervisión médica'],dico:'El ácido fólico es vital antes y durante el embarazo. Toda mujer en edad fértil debería tomarlo.'},
  {e:'💛',n:'Hierro (Sulfato ferroso)',cat:'Vitamina',catCls:'cat-vita',dose:'325 mg',uso:'Suplemento de hierro. Trata y previene la anemia ferropénica.',dosis:'325 mg una o dos veces al día en ayunas.',cuando:'Anemia por déficit de hierro, embarazo, menstruaciones abundantes.',prec:['Puede causar estreñimiento o heces oscuras — normal','Tomar con vitamina C mejora la absorción','No tomar con leche, té ni café'],dico:'El hierro combate la anemia. Tómalo con jugo de naranja — la vitamina C ayuda a absorberlo mucho mejor.'},
  {e:'💛',n:'Calcio + Vitamina D',cat:'Vitamina',catCls:'cat-vita',dose:'600/400 mg/UI',uso:'Suplemento para la salud ósea. Previene osteoporosis.',dosis:'600–1200 mg de calcio con vitamina D al día.',cuando:'Prevención de osteoporosis, mujeres posmenopáusicas, adultos mayores.',prec:['No exceder 2500 mg de calcio/día','Tomar repartido para mejor absorción','Puede causar estreñimiento'],dico:'El calcio con vitamina D es el dúo perfecto para los huesos fuertes. Especialmente importante después de los 50.'},
  {e:'💛',n:'Magnesio',cat:'Vitamina',catCls:'cat-vita',dose:'400 mg',uso:'Mineral esencial para músculos, nervios y regulación de glucosa.',dosis:'400 mg al día en la noche.',cuando:'Calambres musculares, insomnio, suplemento general.',prec:['Dosis altas pueden causar diarrea','Tomar de noche por efecto relajante'],dico:'El magnesio relaja los músculos y ayuda a dormir. Si tienes calambres nocturnos, este puede ser tu aliado.'},
  {e:'🌿',n:'Omega-3',cat:'Vitamina',catCls:'cat-vita',dose:'1000 mg',uso:'Ácidos grasos esenciales. Protegen el corazón y reducen la inflamación.',dosis:'1000 mg una o dos veces al día con las comidas.',cuando:'Suplemento cardiovascular, colesterol elevado, inflamación.',prec:['Tomar con alimentos para evitar sabor residual','Altas dosis pueden afectar la coagulación'],dico:'El omega-3 cuida el corazón y los vasos sanguíneos. El pescado azul es la fuente natural, pero el suplemento también funciona.'},

  // === DERMATOLÓGICOS ===
  {e:'🔴',n:'Aciclovir crema',cat:'Dermatológico',catCls:'cat-derm',dose:'5%',uso:'Antiviral tópico. Trata el herpes labial y herpes simple cutáneo.',dosis:'Aplicar 5 veces al día por 4–5 días.',cuando:'Herpes labial (fuego), herpes cutáneo.',prec:['Aplicar al primer signo de brote','No introducir en boca ni ojos','Lavarse las manos antes y después'],dico:'Apenas sientas ese hormigueo del herpes labial, aplica el aciclovir. Cuanto antes lo uses, mejor resultado.'},
  {e:'🔴',n:'Ketoconazol crema',cat:'Dermatológico',catCls:'cat-derm',dose:'2%',uso:'Antifúngico tópico potente. Trata tiña, caspa y sebodermitis.',dosis:'Aplicar una vez al día por 2–4 semanas.',cuando:'Tiña, dermatitis seborreica, candidiasis cutánea.',prec:['Completar el tratamiento','Mantener piel seca','Evitar contacto con ojos'],dico:'El ketoconazol ataca los hongos con fuerza. Para la caspa también lo hay en champú — muy efectivo.'},
  {e:'🔴',n:'Peróxido de benzoilo',cat:'Dermatológico',catCls:'cat-derm',dose:'5%',uso:'Antibacteriano y queratolítico. Trata el acné inflamatorio.',dosis:'Aplicar capa fina en zonas afectadas una vez al día.',cuando:'Acné moderado, espinillas inflamadas.',prec:['Puede blanquear telas — cuidado con la ropa','Empieza con aplicaciones en días alternos','Puede causar resequedad — usar hidratante'],dico:'El peróxido de benzoilo es muy efectivo para el acné pero puede secar la piel. Empieza despacio y usa hidratante.'},
  {e:'🔴',n:'Betametasona crema',cat:'Dermatológico',catCls:'cat-derm',dose:'0.05%',uso:'Corticoide tópico potente. Trata dermatitis, eccema y psoriasis.',dosis:'Aplicar capa fina 1–2 veces al día.',cuando:'Eccema severo, dermatitis, psoriasis en placa.',prec:['No usar en cara sin indicación médica','Máximo 2 semanas seguidas','Evitar zonas de pliegues en uso prolongado','No aplicar en piel infectada'],dico:'La betametasona es muy potente para la inflamación de piel. Poquito, pocos días y nunca en la cara sin receta.'},
  {e:'🔴',n:'Mupirocina ungüento',cat:'Dermatológico',catCls:'cat-derm',dose:'2%',uso:'Antibiótico tópico. Trata infecciones bacterianas de la piel como impétigo.',dosis:'Aplicar 3 veces al día por 5–10 días.',cuando:'Impétigo, heridas infectadas, foliculitis.',prec:['Solo para infecciones bacterianas','Evitar uso prolongado para no generar resistencia','No aplicar en grandes áreas'],dico:'La mupirocina es el antibiótico de la piel. Para esas heridas que no cicatrizan bien o se infectan.'},
  {e:'🔴',n:'Tretinoína crema',cat:'Dermatológico',catCls:'cat-derm',dose:'0.025%',uso:'Retinoide tópico. Trata el acné y signos de envejecimiento cutáneo.',dosis:'Aplicar una vez al día en la noche, en piel limpia y seca.',cuando:'Acné, manchas, antienvejecimiento — solo con indicación.',prec:['Evitar el sol — siempre usar protector solar','Puede causar descamación al inicio','No usar en embarazo','Empezar con concentración baja'],dico:'La tretinoína es muy poderosa para el acné y las manchas. Pero exige paciencia — los primeros días puede irritar.'},

  // === ANALGÉSICOS/ANTIINFLAMATORIOS ADICIONALES ===
  {e:'🌿',n:'Colchicina',cat:'Analgésico',catCls:'cat-analg',dose:'0.5 mg',uso:'Antiinflamatorio específico para gota y pericarditis.',dosis:'0.5–1.2 mg al inicio del ataque de gota, luego 0.5 mg cada 8 horas.',cuando:'Solo con prescripción. Crisis de gota, pericarditis.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','No exceder la dosis — puede ser tóxica','Puede causar diarrea intensa'],dico:'La colchicina es el tratamiento estrella para los ataques de gota. Funciona muy bien si se toma pronto.'},
  {e:'💊',n:'Pregabalina',cat:'Analgésico',catCls:'cat-analg',dose:'75 mg',uso:'Anticonvulsivante y analgésico neuropático. Trata el dolor nervioso.',dosis:'75–300 mg al día dividido en 2–3 tomas.',cuando:'Solo con prescripción. Neuralgia, fibromialgia, neuropatía diabética.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Puede causar somnolencia y mareos','No conducir al inicio del tratamiento','No suspender bruscamente'],dico:'La pregabalina trata ese dolor quemante o eléctrico de los nervios. Es efectiva pero requiere ajuste gradual de dosis.'},

  // === NEUROLÓGICOS / PSIQUIÁTRICOS ===
  {e:'🧠',n:'Alprazolam',cat:'Analgésico',catCls:'cat-analg',dose:'0.5 mg',uso:'Benzodiazepina de acción rápida. Trata ansiedad y ataques de pánico.',dosis:'0.25–0.5 mg 2–3 veces al día.',cuando:'SOLO CON PRESCRIPCIÓN MÉDICA para ansiedad.',prec:['REQUIERE RECETA MÉDICA CONTROLADA','Alto potencial de dependencia','No combinar con alcohol','No conducir'],dico:'El alprazolam calma la ansiedad rápido, pero crea dependencia. Solo bajo estricto control médico y por el menor tiempo posible.'},
  {e:'🧠',n:'Sertralina',cat:'Analgésico',catCls:'cat-analg',dose:'50 mg',uso:'Antidepresivo ISRS. Trata depresión, ansiedad y trastorno obsesivo-compulsivo.',dosis:'50–200 mg una vez al día.',cuando:'Solo con prescripción. Depresión, trastorno de ansiedad, TOC.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','No suspender bruscamente','Puede tardar 2–4 semanas en hacer efecto','Evitar con IMAO'],dico:'La sertralina es uno de los antidepresivos más seguros. Tiene que pasar un tiempo para que haga efecto — la constancia es clave.'},
  {e:'🧠',n:'Fluoxetina',cat:'Analgésico',catCls:'cat-analg',dose:'20 mg',uso:'Antidepresivo ISRS. Trata depresión, bulimia y trastorno de pánico.',dosis:'20 mg una vez al día por la mañana.',cuando:'Solo con prescripción. Depresión, TOC, trastornos de conducta alimentaria.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Tomar por la mañana para evitar insomnio','Puede causar ansiedad al inicio'],dico:'La fluoxetina es un clásico entre los antidepresivos. Tómala por la mañana para evitar que interfiera con el sueño.'},

  // === OFTALMOLÓGICOS ===
  {e:'👁️',n:'Lágrimas artificiales',cat:'Dermatológico',catCls:'cat-derm',dose:'Colirio',uso:'Lubricantes oculares. Alivian la sequedad y el picor ocular.',dosis:'1–2 gotas en cada ojo según necesidad.',cuando:'Ojo seco, irritación, fatiga visual por pantallas.',prec:['Si contienen conservantes, no usar más de 4 veces/día','Versiones sin conservantes pueden usarse más frecuentemente','Retirar lentes de contacto antes de aplicar'],dico:'Las lágrimas artificiales son el remedio perfecto para los ojos cansados de pantallas. Completamente seguras y muy aliviadoras.'},
  {e:'👁️',n:'Tobramicina colirio',cat:'Antibiótico',catCls:'cat-antib',dose:'0.3%',uso:'Antibiótico oftálmico. Trata conjuntivitis bacteriana.',dosis:'1–2 gotas cada 4 horas en el ojo afectado.',cuando:'Solo con prescripción. Conjuntivitis bacteriana, blefaritis.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','No tocar la punta del gotero al ojo','Lavar manos antes de aplicar','Desechar al finalizar el tratamiento'],dico:'Cuando el ojo está infectado y secreta pus, el tobramicina colirio lo ataca directamente. Higiene al aplicarlo.'},

  // === UROLÓGICOS ===
  {e:'💊',n:'Tamsulosina',cat:'Cardiovascular',catCls:'cat-card',dose:'0.4 mg',uso:'Alfa-bloqueador. Alivia síntomas urinarios por hiperplasia prostática benigna.',dosis:'0.4 mg una vez al día después de las comidas.',cuando:'Solo con prescripción. Hiperplasia prostática, dificultad urinaria.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Puede causar hipotensión ortostática — levantarse despacio','No conducir al inicio del tratamiento'],dico:'La tamsulosina relaja los músculos de la próstata y mejora el flujo urinario. Muy usada en hombres mayores.'},
  {e:'💊',n:'Fenazopiridina',cat:'Analgésico',catCls:'cat-analg',dose:'200 mg',uso:'Analgésico urinario. Alivia el ardor y el dolor al orinar.',dosis:'200 mg tres veces al día después de las comidas.',cuando:'Ardor urinario, cistitis, después de procedimientos urológicos.',prec:['Tiñe la orina de naranja — es normal','No sustituye el antibiótico para la infección','Usar máximo 2 días sin diagnóstico médico'],dico:'La fenazopiridina calma ese ardor horrible al orinar. Ojo: la orina se vuelve naranja — no te asustes, es normal.'},

  // === ANTIPARASITARIOS ===
  {e:'🌿',n:'Albendazol',cat:'Antibiótico',catCls:'cat-antib',dose:'400 mg',uso:'Antiparasitario de amplio espectro. Trata infecciones por helmintos.',dosis:'400 mg dosis única o según indicación.',cuando:'Solo con indicación médica. Parasitosis intestinal, giardia.',prec:['Requiere diagnóstico previo','Evitar en embarazo del primer trimestre','Repetir tratamiento si persisten síntomas a los 15 días'],dico:'El albendazol elimina varios tipos de parásitos intestinales con una sola dosis. Ideal para tratamientos en zonas tropicales.'},
  {e:'🌿',n:'Mebendazol',cat:'Antibiótico',catCls:'cat-antib',dose:'100 mg',uso:'Antiparasitario. Trata infecciones por oxiuros, áscaris y uncinarias.',dosis:'100 mg dos veces al día por 3 días.',cuando:'Solo con indicación médica. Oxiuros, áscaris, anquilostomas.',prec:['Tratar simultáneamente a todos en el hogar para oxiuros','Lavar bien la ropa y ropa de cama','Puede necesitarse segunda tanda'],dico:'Los parásitos intestinales son más comunes de lo que se cree. El mebendazol los elimina de forma efectiva y segura.'},

  // === ANTIMICÓTICOS ===
  {e:'🟣',n:'Fluconazol',cat:'Antibiótico',catCls:'cat-antib',dose:'150 mg',uso:'Antifúngico sistémico. Trata candidiasis oral, vaginal y cutánea.',dosis:'150 mg dosis única para candidiasis vaginal.',cuando:'Solo con prescripción. Candidiasis vaginal, oral (muguet).',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Una sola dosis suele ser suficiente para candidiasis vaginal','Puede interactuar con varios medicamentos'],dico:'El fluconazol resuelve la candidiasis con una sola pastilla. Pero siempre con diagnóstico confirmado.'},
  {e:'🔴',n:'Terbinafina crema',cat:'Dermatológico',catCls:'cat-derm',dose:'1%',uso:'Antifúngico tópico altamente eficaz contra dermatofitos.',dosis:'Aplicar una vez al día por 1–2 semanas.',cuando:'Pie de atleta, tiña corporal, onicomicosis superficial.',prec:['Completar el tratamiento aunque mejore pronto','Mantener la zona seca','Lavar las manos después de aplicar'],dico:'La terbinafina mata los hongos de la piel con más eficacia que otros antifúngicos. Completa el tratamiento para evitar recaídas.'},

  // === OTROS ESENCIALES ===
  {e:'🧴',n:'Alcohol antiséptico 70°',cat:'Dermatológico',catCls:'cat-derm',dose:'70%',uso:'Antiséptico cutáneo. Desinfecta la piel y superficies.',dosis:'Aplicar en la zona a desinfectar con algodón o gasa.',cuando:'Desinfección de heridas leves, preparación de piel antes de inyecciones.',prec:['No aplicar en heridas abiertas profundas','Inflamable — mantener lejos del fuego','No ingerir'],dico:'El alcohol al 70% es el desinfectante básico de cualquier botiquín. A esa concentración mata bacterias eficientemente.'},
  {e:'🩹',n:'Agua oxigenada (H₂O₂)',cat:'Dermatológico',catCls:'cat-derm',dose:'3%',uso:'Antiséptico y limpiador de heridas. Oxigena las lesiones y previene infecciones.',dosis:'Aplicar directamente en la herida con gasa.',cuando:'Heridas superficiales, cortes, raspaduras.',prec:['Solo para heridas superficiales','No usar en heridas profundas o crónicas','No tapar herméticamente la zona después'],dico:'El agua oxigenada limpia la herida y hace esa efervescencia que indica que está actuando. Solo para heridas pequeñas.'},
  {e:'🌿',n:'Povidona yodada',cat:'Dermatológico',catCls:'cat-derm',dose:'10%',uso:'Antiséptico potente de amplio espectro. Para desinfección de heridas y piel.',dosis:'Aplicar en la zona afectada sin diluir o diluida al 1% para mucosas.',cuando:'Heridas, quemaduras leves, preparación quirúrgica.',prec:['No usar en personas con alergia al yodo','Evitar en embarazo y lactancia en grandes áreas','Puede teñir la piel temporalmente'],dico:'La povidona yodada es un antiséptico muy potente. Ideal para heridas con riesgo de infección.'},
  {e:'💊',n:'Dimenhidrinato',cat:'Gastroprotector',catCls:'cat-gast',dose:'50 mg',uso:'Antihistamínico antiemético. Previene y trata el mareo por movimiento.',dosis:'50 mg 30 minutos antes del viaje. Cada 4–6 horas si es necesario.',cuando:'Mareo por viaje (auto, barco, avión), vértigo.',prec:['Causa somnolencia — no conducir','No tomar con alcohol','Evitar en niños menores de 2 años sin indicación'],dico:'¿Te mareas en el carro? El dimenhidrinato es tu aliado. Tómalo antes de salir para que haga efecto a tiempo.'},
  {e:'🌿',n:'Escopolamina',cat:'Gastroprotector',catCls:'cat-gast',dose:'0.33 mg',uso:'Anticolinérgico. Previene el mareo por movimiento y reduce cólicos.',dosis:'1 parche retroauricular 4 horas antes del viaje, o tabletas según indicación.',cuando:'Mareo por viaje prolongado, náuseas postoperatorias.',prec:['Puede causar sequedad de boca y visión borrosa','No conducir','Lavar manos después de manipular el parche'],dico:'El parche de escopolamina es genial para viajes largos en barco o avión. Se pone detrás de la oreja y ya.'},
  {e:'💊',n:'Betahistina',cat:'Cardiovascular',catCls:'cat-card',dose:'16 mg',uso:'Reduce la presión en el oído interno. Trata el vértigo y la enfermedad de Ménière.',dosis:'16 mg dos o tres veces al día con las comidas.',cuando:'Solo con prescripción. Vértigo, enfermedad de Ménière.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Tomar con alimentos','Puede interactuar con antihistamínicos'],dico:'La betahistina es el tratamiento de elección para el vértigo crónico. Mejora la circulación en el oído interno.'},
  {e:'💊',n:'Nistatina suspensión',cat:'Antibiótico',catCls:'cat-antib',dose:'100.000 UI/ml',uso:'Antifúngico para candidiasis oral (muguet) especialmente en bebés.',dosis:'1 ml en cada lado de la boca 4 veces al día.',cuando:'Muguet oral en bebés y adultos inmunosuprimidos.',prec:['Aplicar directamente sobre las lesiones','Completar el tratamiento 48 horas después de mejorar','No deglutir inmediatamente — mantener en boca'],dico:'La nistatina es el tratamiento estándar para el muguet. Muy segura incluso en bebés pequeños.'},
  {e:'🌿',n:'N-acetilcisteína',cat:'Respiratorio',catCls:'cat-resp',dose:'600 mg',uso:'Mucolítico y antioxidante. Fluidifica el moco y protege el hígado en intoxicaciones.',dosis:'600 mg una vez al día o en sobre efervescente.',cuando:'Tos con flema densa, EPOC, bronquitis crónica.',prec:['Puede dar olor a azufre — es normal','Abundante agua potencia su efecto','Puede causar náuseas al inicio'],dico:'La N-acetilcisteína es un mucolítico poderoso que también cuida el hígado. El olor a huevo es normal — no te preocupes.'},
  {e:'🌿',n:'Carbón activado',cat:'Gastroprotector',catCls:'cat-gast',dose:'500 mg',uso:'Adsorbente intestinal. Captura toxinas y gases en el tubo digestivo.',dosis:'25–50 g disuelto en agua en caso de intoxicación (urgente).',cuando:'Intoxicaciones leves, flatulencia excesiva.',prec:['En intoxicaciones: llamar a emergencias PRIMERO','Puede volver las heces negras — es normal','No usar en obstrucción intestinal'],dico:'El carbón activado atrapa las toxinas antes de que el cuerpo las absorba. En intoxicaciones siempre llama a emergencias primero.'},
  {e:'💊',n:'Hidroxizina',cat:'Antihistamínico',catCls:'cat-antih',dose:'25 mg',uso:'Antihistamínico ansiolítico. Trata ansiedad y picazón intensa.',dosis:'25 mg 3–4 veces al día o 50 mg para insomnio.',cuando:'Solo con prescripción. Ansiedad, urticaria severa, insomnio.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Causa sedación importante','No conducir','No combinar con alcohol ni otros sedantes'],dico:'La hidroxizina calma tanto el picor como la ansiedad. Es de las más seguras para el manejo de ansiedad puntual.'},
  {e:'🌿',n:'Probióticos (Lactobacillus)',cat:'Gastroprotector',catCls:'cat-gast',dose:'2.000 Mill UFC',uso:'Restauran la flora intestinal. Útiles durante y después del tratamiento con antibióticos.',dosis:'1 cápsula al día con o sin alimentos.',cuando:'Durante tratamiento antibiótico, diarrea, desequilibrio intestinal.',prec:['Tomar separado del antibiótico por al menos 2 horas','Conservar en frío según indicación del producto'],dico:'Los probióticos son el ejército bueno del intestino. Cuando los antibióticos desequilibran la flora, estos la restauran.'},
  {e:'🌿',n:'Jengibre (extracto)',cat:'Gastroprotector',catCls:'cat-gast',dose:'500 mg',uso:'Antiemético natural. Alivia las náuseas del embarazo, viajes y quimioterapia.',dosis:'500 mg 1–4 veces al día.',cuando:'Náuseas leves, mareo por viaje, náuseas del embarazo.',prec:['Seguro en dosis habituales','Altas dosis pueden interactuar con anticoagulantes','Consultar al médico en embarazo'],dico:'El jengibre es uno de los antinaúseas naturales más eficaces. Muy seguro durante el embarazo para las náuseas matutinas.'},
  {e:'💊',n:'Alopurinol',cat:'Analgésico',catCls:'cat-analg',dose:'100 mg',uso:'Reduce los niveles de ácido úrico en sangre. Previene ataques de gota.',dosis:'100–300 mg al día con abundante agua.',cuando:'Solo con prescripción. Gota crónica, hiperuricemia, cálculos de urato.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','No tomar durante un ataque agudo de gota','Beber mucha agua al día','Puede causar reacciones alérgicas graves — suspender y consultar'],dico:'El alopurinol previene la gota bajando el ácido úrico. No se toma en el ataque sino entre ataques, como prevención.'},
  {e:'🫁',n:'Beclometasona nasal',cat:'Respiratorio',catCls:'cat-resp',dose:'50 mcg',uso:'Corticoide nasal. Reduce la inflamación y congestión en rinitis alérgica crónica.',dosis:'1–2 pulsaciones en cada fosa nasal una o dos veces al día.',cuando:'Rinitis alérgica crónica, poliposis nasal, bajo prescripción.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Efecto máximo después de varios días de uso','No superar la dosis indicada','Enjuagar la boca si llega a garganta'],dico:'La beclometasona nasal no actúa al instante pero su efecto es muy duradero y eficaz. La constancia es la clave.'},
  {e:'💊',n:'Gabapentina',cat:'Analgésico',catCls:'cat-analg',dose:'300 mg',uso:'Anticonvulsivante y analgésico neuropático. Reduce el dolor de nervios dañados.',dosis:'300 mg al inicio, aumentar gradualmente hasta 900–1800 mg/día en 3 tomas.',cuando:'Solo con prescripción. Neuropatía, neuralgia posherpética, epilepsia.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Causa somnolencia — ajustar gradualmente','No suspender bruscamente','Cuidado al conducir al inicio'],dico:'La gabapentina calma el dolor neuropático — ese ardor o descarga eléctrica que viene de los nervios. Requiere paciencia y ajuste gradual.'},
  {e:'💛',n:'Biotina (Vitamina B7)',cat:'Vitamina',catCls:'cat-vita',dose:'5 mg',uso:'Vitamina esencial para la salud del cabello, uñas y metabolismo energético.',dosis:'5 mg al día con el desayuno.',cuando:'Caída del cabello, uñas frágiles, deficiencia de biotina.',prec:['Dosis altas pueden interferir en análisis de laboratorio','Informar al médico si se toman altas dosis antes de exámenes','Generalmente muy bien tolerada'],dico:'La biotina apoya el cabello y las uñas. Si vas a hacerte analíticas, avisa al médico que la tomas — puede alterar algunos resultados.'},

  // === ANALGÉSICOS / ANTIINFLAMATORIOS ===
  {e:'💊',n:'Celecoxib',cat:'Analgésico',catCls:'cat-analg',dose:'200 mg',uso:'Antiinflamatorio inhibidor selectivo de COX-2. Menor riesgo gástrico que el ibuprofeno.',dosis:'200 mg una o dos veces al día con alimentos.',cuando:'Solo con prescripción. Artrosis, artritis reumatoide, dolor crónico.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Evitar en insuficiencia cardíaca o renal','Mayor riesgo cardiovascular con uso prolongado','No combinar con otros AINEs'],dico:'El celecoxib es un antiinflamatorio más amigable con el estómago. Ideal para quienes tienen gastritis pero necesitan controlar la inflamación crónica.'},
  {e:'💊',n:'Tramadol',cat:'Analgésico',catCls:'cat-analg',dose:'50 mg',uso:'Analgésico opioide débil. Trata dolor moderado a intenso cuando otros analgésicos no son suficientes.',dosis:'50–100 mg cada 4–6 horas. Máximo 400 mg/día.',cuando:'Solo con prescripción. Dolor postoperatorio, oncológico, neuropático intenso.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Riesgo de dependencia con uso prolongado','No combinar con alcohol ni antidepresivos','Puede causar convulsiones en dosis altas'],dico:'El tramadol es un analgésico potente para dolores que otros no controlan. Solo bajo supervisión médica estricta.'},
  {e:'🌿',n:'Metamisol (Dipirona)',cat:'Analgésico',catCls:'cat-analg',dose:'500 mg',uso:'Analgésico y antipirético potente. Muy eficaz para cólicos y dolor visceral.',dosis:'500–1000 mg cada 8 horas. Máximo 3 g/día.',cuando:'Dolor cólico (renal, biliar), fiebre resistente, dolor postoperatorio.',prec:['Puede causar agranulocitosis (raro pero grave)','Evitar en embarazo y lactancia','No usar sin diagnóstico claro del cólico'],dico:'La dipirona es excelente para el cólico renal o biliar — ese dolor que te dobla. Pero siempre es importante saber la causa del dolor primero.'},
  {e:'💊',n:'Pregabalina',cat:'Analgésico',catCls:'cat-analg',dose:'75 mg',uso:'Anticonvulsivante y analgésico neuropático. Trata el dolor crónico de nervios.',dosis:'75 mg dos veces al día; puede aumentarse a 150–300 mg/día.',cuando:'Solo con prescripción. Neuropatía diabética, fibromialgia, neuralgia.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Causa mareos y somnolencia al inicio','No suspender bruscamente','Puede causar dependencia'],dico:'La pregabalina calma el dolor de nervios desde la raíz. Al principio puede marear — el cuerpo se adapta con el tiempo.'},

  // === ANTIBIÓTICOS ===
  {e:'💊',n:'Clindamicina',cat:'Antibiótico',catCls:'cat-antib',dose:'300 mg',uso:'Antibiótico lincosamida. Activo contra bacterias anaerobias y gram-positivas.',dosis:'300–450 mg cada 6–8 horas con alimentos.',cuando:'Solo con prescripción. Infecciones dentales, piel, pelvis, abscesos.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Puede causar colitis pseudomembranosa','Completar el tratamiento','Tomar con alimentos para reducir molestias gástricas'],dico:'La clindamicina es muy eficaz para infecciones dentales y de partes blandas. Si tienes diarrea muy intensa durante el tratamiento, avisa al médico.'},
  {e:'💊',n:'Nitrofurantoína',cat:'Antibiótico',catCls:'cat-antib',dose:'100 mg',uso:'Antibiótico urinario. Solo actúa en el tracto urinario, ideal para cistitis sin complicaciones.',dosis:'100 mg cada 12 horas por 5–7 días con alimentos.',cuando:'Solo con prescripción. Infección urinaria baja (cistitis).',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Tomar con alimentos para reducir náuseas','No usar en insuficiencia renal','Puede teñir la orina de amarillo oscuro — es normal'],dico:'La nitrofurantoína ataca la infección directamente en la vejiga. La orina oscura es normal — no te asustes.'},
  {e:'💊',n:'Metronidazol',cat:'Antibiótico',catCls:'cat-antib',dose:'500 mg',uso:'Antibiótico y antiprotozoario. Activo contra anaerobios y parásitos como Giardia y Trichomonas.',dosis:'500 mg cada 8 horas por 7 días.',cuando:'Solo con prescripción. Giardiasis, tricomoniasis, infecciones anaerobias.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Evitar alcohol completamente durante el tratamiento y 48h después','Puede causar sabor metálico en la boca','Contraindicado en el primer trimestre de embarazo'],dico:'El metronidazol es muy eficaz pero no tolera nada de alcohol. Ni una gota durante el tratamiento — puede dar una reacción muy desagradable.'},
  {e:'💊',n:'Doxiciclina',cat:'Antibiótico',catCls:'cat-antib',dose:'100 mg',uso:'Antibiótico tetraciclina de amplio espectro. También trata acné y enfermedades tropicales.',dosis:'100 mg cada 12 horas con abundante agua.',cuando:'Solo con prescripción. Acné severo, neumonía atípica, malaria (profilaxis).',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','No tomar acostado — puede dañar el esófago','Evitar exposición solar intensa','No usar en menores de 8 años ni en embarazo'],dico:'La doxiciclina es muy versátil — sirve para acné, infecciones respiratorias y hasta profilaxis de malaria. Siempre con agua abundante y erguido.'},
  {e:'💊',n:'Cefadroxilo',cat:'Antibiótico',catCls:'cat-antib',dose:'500 mg',uso:'Cefalosporina de primera generación. Trata infecciones de piel, amígdalas y urinarias.',dosis:'500 mg cada 12 horas por 7–10 días.',cuando:'Solo con prescripción. Amigdalitis estreptocócica, impétigo, cistitis.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Avisar si hay alergia a penicilinas','Completar el tratamiento completo','Puede causar molestias gástricas leves'],dico:'El cefadroxilo es un antibiótico de primera línea muy fiable para infecciones de garganta y piel. Completa los días indicados aunque te sientas mejor.'},

  // === CARDIOVASCULAR ===
  {e:'❤️',n:'Enalapril',cat:'Cardiovascular',catCls:'cat-card',dose:'10 mg',uso:'IECA. Reduce la presión arterial y protege el corazón y los riñones.',dosis:'5–20 mg una o dos veces al día.',cuando:'Solo con prescripción. Hipertensión, insuficiencia cardíaca, protección renal en diabetes.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Puede causar tos seca persistente','Contraindicado en embarazo','Controlar potasio y función renal periódicamente'],dico:'El enalapril baja la presión y cuida el corazón al mismo tiempo. Si te da tos seca, coméntaselo al médico — hay alternativas.'},
  {e:'❤️',n:'Losartán',cat:'Cardiovascular',catCls:'cat-card',dose:'50 mg',uso:'ARA-II. Antihipertensivo que bloquea la angiotensina. Sin el efecto de tos del enalapril.',dosis:'50 mg una vez al día. Puede aumentarse a 100 mg.',cuando:'Solo con prescripción. Hipertensión, insuficiencia cardíaca, nefropatía diabética.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Contraindicado en embarazo','Controlar potasio y función renal','No combinar con enalapril'],dico:'El losartán es la alternativa al enalapril para quienes no toleran la tos. Igual de eficaz para la presión y los riñones.'},
  {e:'❤️',n:'Bisoprolol',cat:'Cardiovascular',catCls:'cat-card',dose:'5 mg',uso:'Betabloqueante cardioselectivo. Reduce la frecuencia cardíaca y la presión arterial.',dosis:'5–10 mg una vez al día por la mañana.',cuando:'Solo con prescripción. Hipertensión, insuficiencia cardíaca, arritmias.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','No suspender bruscamente — riesgo cardíaco','Cuidado en asma o EPOC','Puede enmascarar síntomas de hipoglucemia'],dico:'El bisoprolol desacelera el corazón y lo protege. Nunca se suspende de golpe — siempre hay que ir bajando la dosis gradualmente.'},
  {e:'❤️',n:'Furosemida',cat:'Cardiovascular',catCls:'cat-card',dose:'40 mg',uso:'Diurético de asa potente. Elimina el exceso de líquidos en el cuerpo.',dosis:'20–80 mg por la mañana.',cuando:'Solo con prescripción. Insuficiencia cardíaca con edema, edema pulmonar, hipertensión grave.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Tomar por la mañana para evitar orinar de noche','Controlar potasio — puede causar hipopotasemia','Vigilar presión arterial'],dico:'La furosemida es un diurético potente que saca el agua que el corazón no puede mover. Se toma de mañana para no levantarse de noche.'},
  {e:'❤️',n:'Espironolactona',cat:'Cardiovascular',catCls:'cat-card',dose:'25 mg',uso:'Diurético ahorrador de potasio. Trata insuficiencia cardíaca y edema.',dosis:'25–50 mg una vez al día.',cuando:'Solo con prescripción. Insuficiencia cardíaca, edema, hiperaldosteronismo.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Puede elevar el potasio — controlar analíticas','Puede causar ginecomastia en hombres con uso prolongado','No combinar con suplementos de potasio'],dico:'La espironolactona retiene el potasio mientras elimina el agua. Es un diurético especial que protege el corazón a largo plazo.'},
  {e:'💊',n:'Warfarina',cat:'Cardiovascular',catCls:'cat-card',dose:'5 mg',uso:'Anticoagulante oral. Previene y trata trombosis y embolias.',dosis:'Dosis individualizada según INR (generalmente 2–10 mg/día).',cuando:'Solo con prescripción. Fibrilación auricular, trombosis venosa, válvulas protésicas.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Control frecuente de INR','Muchas interacciones con alimentos y medicamentos','Evitar deportes de contacto — riesgo de sangrado'],dico:'La warfarina adelgaza la sangre para evitar coágulos peligrosos. Requiere controles frecuentes — la dosis se ajusta según resultados.'},

  // === RESPIRATORIO ===
  {e:'🫁',n:'Montelukast',cat:'Respiratorio',catCls:'cat-resp',dose:'10 mg',uso:'Antileucotrieno. Previene el asma y alivia la rinitis alérgica crónica.',dosis:'10 mg una vez al día por la noche.',cuando:'Solo con prescripción. Asma leve a moderada, rinitis alérgica persistente.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Tomar por la noche','No sirve como broncodilatador de rescate','Puede causar cambios de humor — avisar al médico'],dico:'El montelukast previene el asma y la alergia nasal desde adentro. No alivia una crisis — es para la prevención diaria.'},
  {e:'🫁',n:'Tiotropio',cat:'Respiratorio',catCls:'cat-resp',dose:'18 mcg',uso:'Broncodilatador anticolinérgico de larga duración. Para EPOC y asma grave.',dosis:'1 inhalación al día con el dispositivo HandiHaler.',cuando:'Solo con prescripción. EPOC, asma no controlada.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','No usar como rescate','Puede causar sequedad de boca','Cuidado en glaucoma y próstata'],dico:'El tiotropio abre los bronquios durante 24 horas con solo una inhalación diaria. Es el tratamiento de mantenimiento en el EPOC.'},
  {e:'🫁',n:'Bromuro de ipratropio',cat:'Respiratorio',catCls:'cat-resp',dose:'20 mcg',uso:'Broncodilatador anticolinérgico de acción corta. Alivia el broncoespasmo en EPOC.',dosis:'2–3 pulsaciones cada 6–8 horas.',cuando:'Solo con prescripción. EPOC, crisis bronquial, bronquitis crónica.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','No mezclar en el nebulizador con salbutamol sin indicación','Puede causar sequedad de boca','Cuidado en glaucoma'],dico:'El ipratropio es complemento ideal del salbutamol en las crisis de EPOC. Actúan por mecanismos distintos y se potencian.'},
  {e:'🫁',n:'Fluticasona inhalada',cat:'Respiratorio',catCls:'cat-resp',dose:'250 mcg',uso:'Corticoide inhalado. Reduce la inflamación crónica de las vías aéreas en asma y EPOC.',dosis:'1–2 pulsaciones dos veces al día.',cuando:'Solo con prescripción. Asma moderada a grave, EPOC con exacerbaciones frecuentes.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Enjuagar la boca después de cada uso — previene candidiasis oral','No suspender bruscamente','No sirve para crisis agudas'],dico:'La fluticasona inhalada apaga la inflamación bronquial de fondo. Enjuaga la boca siempre después de usarla para evitar hongos.'},
  {e:'🌿',n:'Guaifenesina',cat:'Respiratorio',catCls:'cat-resp',dose:'400 mg',uso:'Expectorante. Fluidifica las secreciones bronquiales para facilitar su expulsión.',dosis:'400 mg cada 4 horas con abundante agua.',cuando:'Tos productiva con moco espeso, bronquitis, resfriado con congestión.',prec:['Beber mucho líquido potencia el efecto','Evitar en niños menores de 2 años','No es un supresor de tos — aumenta la tos para expulsar el moco'],dico:'La guaifenesina hace que el moco sea más fluido para que puedas expulsarlo mejor. Bebe mucha agua — el agua es su mejor aliado.'},

  // === GASTROPROTECTORES / DIGESTIVOS ===
  {e:'🟢',n:'Lansoprazol',cat:'Gastroprotector',catCls:'cat-gast',dose:'30 mg',uso:'Inhibidor de bomba de protones. Reduce la acidez gástrica de forma potente.',dosis:'30 mg una vez al día antes del desayuno.',cuando:'Úlcera gástrica, esofagitis por reflujo, erradicación de H. pylori.',prec:['Tomar 30 minutos antes de comer','Uso prolongado puede reducir absorción de magnesio y B12','Puede enmascarar síntomas de cáncer gástrico'],dico:'El lansoprazol bloquea la producción de ácido con mucha eficacia. Para que funcione bien, tómalo 30 minutos antes de desayunar.'},
  {e:'🟢',n:'Pantoprazol',cat:'Gastroprotector',catCls:'cat-gast',dose:'40 mg',uso:'Inhibidor de bomba de protones. Similar al omeprazol, muy usado hospitalariamente.',dosis:'40 mg una vez al día antes del desayuno.',cuando:'Reflujo gastroesofágico, úlcera péptica, síndrome de Zollinger-Ellison.',prec:['Tomar en ayunas','Uso crónico puede afectar niveles de magnesio','Consultar al médico si los síntomas persisten más de 4 semanas'],dico:'El pantoprazol es el protector de estómago favorito del hospital. Funciona de forma muy similar al omeprazol pero a veces se tolera mejor.'},
  {e:'💊',n:'Domperidona',cat:'Gastroprotector',catCls:'cat-gast',dose:'10 mg',uso:'Procinético. Acelera el vaciado gástrico y alivia náuseas y vómitos.',dosis:'10 mg 3 veces al día 30 minutos antes de las comidas.',cuando:'Solo con prescripción. Náuseas, reflujo, gastroparesia.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','No usar más de 1 semana sin indicación','Puede prolongar el intervalo QT — riesgo cardíaco','Evitar en insuficiencia hepática grave'],dico:'La domperidona hace que el estómago se vacíe más rápido y corta las náuseas. No debe tomarse por períodos largos sin supervisión.'},
  {e:'🟤',n:'Bismuto subsalicilato',cat:'Gastroprotector',catCls:'cat-gast',dose:'524 mg',uso:'Protege la mucosa gástrica. Alivia indigestión, diarrea y náuseas.',dosis:'524 mg (30 ml) cada 30–60 minutos según necesidad. Máximo 8 dosis/día.',cuando:'Diarrea del viajero, indigestión, náuseas, ardor estomacal.',prec:['No usar en niños con fiebre por riesgo de síndrome de Reye','Puede volver la lengua y las heces negras — es normal','Evitar con anticoagulantes'],dico:'El bismuto crea una capa protectora sobre la mucosa. La lengua y las heces negras son normales — no te asustes.'},
  {e:'🌿',n:'Simeticona',cat:'Gastroprotector',catCls:'cat-gast',dose:'80 mg',uso:'Antiespumante intestinal. Elimina los gases acumulados en el estómago e intestino.',dosis:'80–125 mg después de cada comida y al acostarse.',cuando:'Gases, hinchazón, cólico del lactante.',prec:['Muy segura — puede usarse en bebés','No es absorbida por el cuerpo','Masticar bien las tabletas o agitar bien la suspensión'],dico:'La simeticona rompe las burbujas de gas en el intestino y las elimina. Muy segura para bebés con cólicos.'},

  // === ENDOCRINOLOGÍA / DIABETES ===
  {e:'💊',n:'Metformina',cat:'Cardiovascular',catCls:'cat-card',dose:'850 mg',uso:'Antidiabético oral de primera línea. Reduce la glucosa sin causar hipoglucemia.',dosis:'850 mg dos o tres veces al día con las comidas.',cuando:'Solo con prescripción. Diabetes tipo 2, resistencia a la insulina.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Suspender antes de contrastes yodados (72 h)','Puede causar molestias gástricas — tomar con comida','Contraindicada en insuficiencia renal grave'],dico:'La metformina es el pilar del tratamiento de la diabetes tipo 2. Es segura, económica y protege el corazón. El estómago se adapta con el tiempo.'},
  {e:'💊',n:'Glibenclamida',cat:'Cardiovascular',catCls:'cat-card',dose:'5 mg',uso:'Sulfonilurea. Estimula la secreción de insulina para reducir el azúcar en sangre.',dosis:'2.5–5 mg antes del desayuno.',cuando:'Solo con prescripción. Diabetes tipo 2 cuando la metformina no es suficiente.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Riesgo de hipoglucemia — no saltarse comidas','Evitar en insuficiencia renal o hepática','Evitar en adultos mayores frágiles'],dico:'La glibenclamida hace que el páncreas produzca más insulina. Es eficaz pero hay que comer a sus horas — si no, puede bajar demasiado el azúcar.'},
  {e:'💊',n:'Levotiroxina',cat:'Vitamina',catCls:'cat-vita',dose:'50 mcg',uso:'Hormona tiroidea sintética. Trata el hipotiroidismo reemplazando la hormona que falta.',dosis:'25–100 mcg en ayunas 30 minutos antes del desayuno.',cuando:'Solo con prescripción. Hipotiroidismo, bocio, cáncer de tiroides postoperatorio.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Tomar siempre en ayunas y a la misma hora','No mezclar con calcio, hierro ni antiácidos en las mismas horas','Controles periódicos de TSH'],dico:'La levotiroxina reemplaza la hormona que la tiroides no produce. La hora y el ayuno son clave para que se absorba bien.'},

  // === DERMATOLOGÍA ===
  {e:'🧴',n:'Hidrocortisona crema',cat:'Dermatológico',catCls:'cat-derm',dose:'1%',uso:'Corticoide tópico leve. Reduce el picor y la inflamación en dermatitis y eccema.',dosis:'Aplicar una capa fina en la zona afectada 2 veces al día.',cuando:'Dermatitis de contacto, eccema leve, picaduras, sarpullido.',prec:['No usar en cara más de 7 días sin indicación','No aplicar en infecciones cutáneas','Evitar uso prolongado — adelgaza la piel','No usar en ojos'],dico:'La hidrocortisona es el corticoide de baja potencia para calmar el picor y la inflamación de la piel. Ideal para reacciones leves y picaduras.'},
  {e:'🧴',n:'Betametasona crema',cat:'Dermatológico',catCls:'cat-derm',dose:'0.05%',uso:'Corticoide tópico potente. Trata inflamaciones cutáneas más graves como psoriasis y dermatitis.',dosis:'Aplicar una capa fina en la zona afectada una vez al día.',cuando:'Solo con prescripción. Psoriasis, dermatitis atópica grave, liquen plano.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','No usar en cara ni zonas de pliegues sin indicación','Uso prolongado puede causar atrofia cutánea','Evitar en niños pequeños'],dico:'La betametasona es un corticoide potente para la piel. Funciona muy bien pero no se puede usar indefinidamente — la piel se adelgaza.'},
  {e:'🧴',n:'Mupirocina ungüento',cat:'Dermatológico',catCls:'cat-derm',dose:'2%',uso:'Antibiótico tópico. Trata impétigo y heridas infectadas por bacterias gram-positivas.',dosis:'Aplicar en la zona 3 veces al día por 5–10 días.',cuando:'Solo con prescripción. Impétigo, foliculitis, heridas infectadas superficiales.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Solo para uso cutáneo','No aplicar en mucosas ni en zonas extensas','Completar el tratamiento'],dico:'La mupirocina es un antibiótico que se aplica directamente sobre las lesiones de la piel infectadas. Muy eficaz para el impétigo.'},
  {e:'🧴',n:'Aciclovir crema',cat:'Dermatológico',catCls:'cat-derm',dose:'5%',uso:'Antiviral tópico. Trata el herpes labial (fuego) reduciendo la duración y el dolor.',dosis:'Aplicar 5 veces al día cada 4 horas por 5 días.',cuando:'Herpes labial (HSV-1) al primer signo de hormigueo.',prec:['Aplicar al primer síntoma para mayor eficacia','Lavarse las manos antes y después','No aplicar en la boca ni en ojos','No es una cura — el virus permanece latente'],dico:'El aciclovir en crema es más eficaz cuanto antes se aplique — al primer hormigueo. No cura el herpes pero acorta el episodio significativamente.'},
  {e:'🧴',n:'Zinc óxido pasta',cat:'Dermatológico',catCls:'cat-derm',dose:'20%',uso:'Protector y cicatrizante cutáneo. Ideal para dermatitis del pañal y heridas superficiales.',dosis:'Aplicar una capa generosa en la zona a proteger.',cuando:'Dermatitis del pañal, rozaduras, eccemas húmedos.',prec:['Solo para uso externo','No aplicar sobre infecciones activas','Retirar con aceite suavemente — no frotar','Seguro para bebés'],dico:'La pasta de óxido de zinc crea una barrera protectora perfecta para el culito del bebé. Es el tratamiento clásico de la dermatitis del pañal.'},
  {e:'🌿',n:'Permetrina crema',cat:'Dermatológico',catCls:'cat-derm',dose:'5%',uso:'Antiparasitario tópico. Elimina la sarna y los piojos del cuero cabelludo.',dosis:'Aplicar en todo el cuerpo (sarna) o en el cabello (piojos) y lavar tras el tiempo indicado.',cuando:'Solo con indicación médica. Escabiosis (sarna), pediculosis.',prec:['Tratar a todos los contactos del hogar simultáneamente','Lavar ropa y ropa de cama a alta temperatura','Puede causar irritación transitoria de la piel','Segunda aplicación a los 7 días para sarna'],dico:'La permetrina elimina la sarna y los piojos de forma muy eficaz. Toda la familia debe tratarse a la vez para evitar reinfecciones.'},

  // === VITAMINAS Y SUPLEMENTOS ===
  {e:'🟠',n:'Vitamina A',cat:'Vitamina',catCls:'cat-vita',dose:'5000 UI',uso:'Esencial para la visión, el sistema inmunológico y la piel.',dosis:'5000 UI al día con alimentos que contengan grasa.',cuando:'Deficiencia de vitamina A, visión nocturna reducida, piel seca.',prec:['No superar las dosis recomendadas — toxicidad por acumulación','Contraindicada en dosis altas durante el embarazo','Tomar con alimentos grasos para mejor absorción'],dico:'La vitamina A cuida los ojos y la piel. A diferencia de las vitaminas del grupo B, se acumula en el cuerpo — no hay que pasarse con la dosis.'},
  {e:'🔵',n:'Vitamina B12 (Cianocobalamina)',cat:'Vitamina',catCls:'cat-vita',dose:'1000 mcg',uso:'Esencial para la función neurológica, formación de glóbulos rojos y el metabolismo.',dosis:'1000 mcg al día vía oral o intramuscular.',cuando:'Anemia megaloblástica, deficiencia en veganos, neuropatía por déficit.',prec:['Los veganos deben suplementarla siempre','Se absorbe mal en personas mayores — vigilar niveles','La inyección IM tiene mayor biodisponibilidad que la oral'],dico:'La B12 es la vitamina que los veganos y adultos mayores suelen necesitar suplementar. Es fundamental para los nervios y la sangre.'},
  {e:'🟡',n:'Ácido fólico',cat:'Vitamina',catCls:'cat-vita',dose:'400 mcg',uso:'Vitamina B9. Esencial para la formación del tubo neural y la división celular.',dosis:'400 mcg al día. En embarazo: 400–800 mcg desde 1 mes antes de la concepción.',cuando:'Planificación del embarazo, embarazo, anemia megaloblástica.',prec:['Comenzar 1 mes antes del embarazo idealmente','Dosis altas (>1 mg) solo bajo indicación médica','Puede enmascarar deficiencia de B12'],dico:'El ácido fólico es fundamental antes y durante el embarazo para prevenir defectos del tubo neural. Toda mujer que busca embarazo debería tomarlo.'},
  {e:'🟤',n:'Hierro (Sulfato ferroso)',cat:'Vitamina',catCls:'cat-vita',dose:'325 mg',uso:'Suplemento de hierro para tratar y prevenir la anemia ferropénica.',dosis:'325 mg (65 mg de hierro elemental) una o dos veces al día en ayunas.',cuando:'Solo con diagnóstico. Anemia por déficit de hierro, embarazo, menstruación abundante.',prec:['Tomar en ayunas o con vitamina C para mejor absorción','Puede causar estreñimiento y heces oscuras — es normal','Evitar con té, café, calcio o antiácidos','No tomar sin confirmar anemia ferropénica'],dico:'El hierro reconstruye los glóbulos rojos cuando hay anemia. El café y el calcio bloquean su absorción — tómalo separado de ellos.'},
  {e:'🦴',n:'Vitamina K2',cat:'Vitamina',catCls:'cat-vita',dose:'100 mcg',uso:'Dirige el calcio a los huesos y arterias. Complementa a la vitamina D3.',dosis:'100 mcg al día con alimentos grasos.',cuando:'Osteoporosis, calcificación arterial, suplementación junto a vitamina D.',prec:['Tomar con alimentos que contengan grasa','Puede interactuar con anticoagulantes — consultar al médico','Combinada con D3 para mayor eficacia'],dico:'La vitamina K2 lleva el calcio adonde debe ir: a los huesos, no a las arterias. Siempre combínala con vitamina D3 para mejores resultados.'},
  {e:'🧪',n:'Magnesio glicinato',cat:'Vitamina',catCls:'cat-vita',dose:'400 mg',uso:'Suplemento de magnesio. Alivia calambres, mejora el sueño y reduce la ansiedad leve.',dosis:'400 mg al día por la noche.',cuando:'Calambres musculares, insomnio leve, déficit de magnesio.',prec:['Altas dosis pueden causar diarrea','La forma glicinato es la mejor tolerada gástricamente','Tomar por la noche para aprovechar el efecto relajante'],dico:'El magnesio glicinato relaja los músculos y mejora el sueño. Tómalo de noche — notarás la diferencia en la calidad del descanso.'},

  // === OFTALMOLOGÍA ===
  {e:'👁️',n:'Timolol colirio',cat:'Cardiovascular',catCls:'cat-card',dose:'0.5%',uso:'Betabloqueante oftálmico. Reduce la presión intraocular en el glaucoma.',dosis:'1 gota en el ojo afectado dos veces al día.',cuando:'Solo con prescripción. Glaucoma de ángulo abierto, hipertensión ocular.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Puede absorberse sistémicamente — cuidado en asma y bloqueo cardíaco','Presionar el lagrimal 1 minuto tras la aplicación reduce absorción sistémica'],dico:'El timolol baja la presión del ojo para proteger el nervio óptico. Aunque es un colirio, se absorbe algo al torrente sanguíneo — avisa si tienes asma.'},
  {e:'👁️',n:'Ciprofloxacino colirio',cat:'Antibiótico',catCls:'cat-antib',dose:'0.3%',uso:'Antibiótico fluoroquinolona oftálmico. Trata infecciones oculares bacterianas graves.',dosis:'1–2 gotas en el ojo afectado cada 2–4 horas los primeros días.',cuando:'Solo con prescripción. Conjuntivitis bacteriana grave, úlcera corneal.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','No tocar la punta del gotero','No usar lentes de contacto durante el tratamiento','Completar el tratamiento prescrito'],dico:'El ciprofloxacino oftálmico es el antibiótico más potente para infecciones serias del ojo. Solo con receta y siempre con higiene.'},

  // === NEUROLOGÍA / PSIQUIATRÍA ===
  {e:'🧠',n:'Alprazolam',cat:'Analgésico',catCls:'cat-analg',dose:'0.25 mg',uso:'Benzodiacepina. Trata la ansiedad aguda y los ataques de pánico.',dosis:'0.25–0.5 mg tres veces al día.',cuando:'Solo con prescripción. Trastorno de ansiedad, ataques de pánico.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Alto riesgo de dependencia — uso corto plazo','No combinar con alcohol','No suspender bruscamente — puede causar convulsiones'],dico:'El alprazolam calma la ansiedad rápido, pero es adictivo. Solo para crisis puntuales y siempre bajo supervisión médica.'},
  {e:'🧠',n:'Clonazepam',cat:'Analgésico',catCls:'cat-analg',dose:'0.5 mg',uso:'Benzodiacepina anticonvulsivante. Trata epilepsia, ansiedad y trastorno de pánico.',dosis:'0.5–2 mg dos o tres veces al día.',cuando:'Solo con prescripción. Epilepsia, trastorno de pánico, ansiedad severa.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Riesgo de dependencia con uso prolongado','No suspender bruscamente','Evitar con alcohol y otros depresores del SNC'],dico:'El clonazepam es más duradero que el alprazolam. Se usa para la epilepsia y la ansiedad severa siempre con seguimiento médico estrecho.'},
  {e:'🧠',n:'Quetiapina',cat:'Analgésico',catCls:'cat-analg',dose:'25 mg',uso:'Antipsicótico atípico. Trata esquizofrenia, bipolaridad e insomnio en dosis bajas.',dosis:'25–50 mg para insomnio; 150–800 mg para psicosis.',cuando:'Solo con prescripción. Esquizofrenia, trastorno bipolar, insomnio crónico.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','Puede causar aumento de peso y somnolencia','Controlar glucosa y lípidos periódicamente','No conducir al inicio del tratamiento'],dico:'La quetiapina en dosis bajas se usa para el insomnio refractario. En dosis altas, controla la psicosis. Siempre bajo supervisión estricta.'},
  {e:'🧠',n:'Melatonina',cat:'Vitamina',catCls:'cat-vita',dose:'3 mg',uso:'Hormona reguladora del sueño. Ayuda a conciliar el sueño y reajustar el ritmo circadiano.',dosis:'0.5–3 mg 30–60 minutos antes de dormir.',cuando:'Insomnio leve, jet lag, trastornos del sueño.',prec:['Empezar con la dosis más baja posible','No producirá sueño inmediato como un somnífero','Evitar en embarazo por falta de estudios','Puede interactuar con anticoagulantes'],dico:'La melatonina no da sueño como un somnífero — le dice al cuerpo que es de noche. Perfecta para el jet lag o cuando el ritmo circadiano está desordenado.'},

  // === OTROS ESENCIALES DE FARMACIA ===
  {e:'💊',n:'Colchicina',cat:'Analgésico',catCls:'cat-analg',dose:'0.5 mg',uso:'Antiinflamatorio específico para la gota aguda. Reduce el dolor del ataque.',dosis:'0.5–1 mg al inicio, 0.5 mg cada 1–2 horas hasta mejoría.',cuando:'Solo con prescripción. Ataque agudo de gota, pericarditis.',prec:['REQUIERE PRESCRIPCIÓN MÉDICA','No superar la dosis máxima — toxicidad grave','Puede causar diarrea severa como señal de sobredosis','Precaución en insuficiencia renal o hepática'],dico:'La colchicina corta el ataque de gota en cuestión de horas. Hay que respetar la dosis máxima — si empieza la diarrea, es señal de parar.'},
  {e:'🌿',n:'Valeriana (extracto)',cat:'Vitamina',catCls:'cat-vita',dose:'450 mg',uso:'Sedante suave natural. Ayuda a conciliar el sueño y reduce la ansiedad leve.',dosis:'300–600 mg 30–60 minutos antes de dormir.',cuando:'Insomnio leve, ansiedad puntual, estrés.',prec:['Efecto completo puede tardar 2–4 semanas','No combinar con alcohol ni sedantes','Puede causar somnolencia al día siguiente inicialmente','Suspender antes de cirugías'],dico:'La valeriana es el somnífero natural más estudiado. No actúa en la primera noche — hay que darle unas semanas para que funcione.'},
  {e:'🌿',n:'Pasiflora (extracto)',cat:'Vitamina',catCls:'cat-vita',dose:'250 mg',uso:'Ansiolítico natural suave. Reduce la ansiedad y mejora la calidad del sueño.',dosis:'250 mg 2–3 veces al día o 500 mg antes de dormir.',cuando:'Ansiedad leve, insomnio por nerviosismo, estrés.',prec:['Puede causar somnolencia','No combinar con sedantes farmacológicos','Suspender 2 semanas antes de cirugía','Evitar en embarazo'],dico:'La pasiflora calma la ansiedad suavemente. Muchas personas la prefieren porque no genera dependencia como las benzodiacepinas.'},
  {e:'🧴',n:'Dexpantenol crema',cat:'Dermatológico',catCls:'cat-derm',dose:'5%',uso:'Provitamina B5. Hidrata, regenera y cicatriza la piel dañada o irritada.',dosis:'Aplicar en la zona afectada 2–3 veces al día.',cuando:'Quemaduras leves, dermatitis del pañal, heridas superficiales, piel seca.',prec:['Solo para uso externo','Seguro para bebés y embarazadas','No aplicar en heridas infectadas','Puede usarse con apósito encima'],dico:'El dexpantenol es la crema cicatrizante por excelencia. Hidrata la piel dañada y acelera su reparación. Muy seguro para toda la familia.'},
  {e:'💊',n:'Clorfenamina',cat:'Antihistamínico',catCls:'cat-antih',dose:'4 mg',uso:'Antihistamínico de primera generación. Alivia la alergia y el resfriado. Causa sedación.',dosis:'4 mg cada 6–8 horas.',cuando:'Alergia, urticaria, resfriado con rinorrea, picaduras.',prec:['Causa somnolencia significativa — no conducir','No tomar con alcohol','Evitar en hipertrofia prostática','Puede causar boca seca y estreñimiento'],dico:'La clorfenamina es el antihistamínico clásico que te da sueño. Ideal para tomarlo de noche o cuando no necesitas conducir.'},
  {e:'💊',n:'Fexofenadina',cat:'Antihistamínico',catCls:'cat-antih',dose:'180 mg',uso:'Antihistamínico de segunda generación no sedante. Alivia la alergia sin causar sueño.',dosis:'180 mg una vez al día.',cuando:'Rinitis alérgica, urticaria crónica, alergia estacional.',prec:['Evitar jugo de pomelo, naranja o manzana al tomar — reduce absorción','No suele causar somnolencia','Puede usarse en adultos mayores con más seguridad'],dico:'La fexofenadina es el antihistamínico perfecto para quien necesita estar activo. Sin sueño, sin mareos — solo alivio de la alergia.'},
  {e:'🌿',n:'Ácido hialurónico oral',cat:'Vitamina',catCls:'cat-vita',dose:'120 mg',uso:'Apoya la hidratación de articulaciones y piel. Complemento en osteoartritis.',dosis:'120 mg una vez al día.',cuando:'Dolor articular leve, piel seca, osteoartritis incipiente.',prec:['Evidencia moderada — no sustituye tratamiento médico','Puede tardar semanas en mostrar resultados','Generalmente bien tolerado'],dico:'El ácido hialurónico oral lubrica las articulaciones y la piel desde adentro. Los resultados son graduales — dale tiempo.'},
  {e:'🦴',n:'Condroitín + Glucosamina',cat:'Vitamina',catCls:'cat-vita',dose:'400/500 mg',uso:'Suplemento para el cartílago articular. Reduce el dolor y enlentece el deterioro en osteoartritis.',dosis:'1 comprimido dos veces al día con las comidas.',cuando:'Osteoartritis, dolor articular crónico de rodillas, cadera.',prec:['Efecto a partir de 6–8 semanas de uso','Puede interactuar con anticoagulantes','Consultar al médico si hay alergia a mariscos (la glucosamina puede derivar de ellos)'],dico:'El condroitín y la glucosamina alimentan el cartílago de las articulaciones. La clave es la constancia — en semanas notarás la diferencia.'},
  {e:'💊',n:'Piridoxina (Vitamina B6)',cat:'Vitamina',catCls:'cat-vita',dose:'50 mg',uso:'Vitamina B6. Alivia las náuseas del embarazo y apoya el sistema nervioso.',dosis:'10–50 mg al día según indicación.',cuando:'Náuseas del embarazo (con doxilamina), deficiencia de B6, síndrome premenstrual.',prec:['Dosis altas (>500 mg/día) pueden causar neuropatía','Muy segura en dosis habituales','Para náuseas del embarazo combinar con doxilamina según indicación médica'],dico:'La vitamina B6 es el tratamiento de primera línea para las náuseas del embarazo. En dosis normales es completamente segura para madre y bebé.'}
];